/**
 * frontend/src/Enrollment.jsx - SANS LIMITES
 * À REMPLACER
 * ✅ Accepte tous les formats image
 * ✅ Pas de limite taille
 */

import React, { useState } from 'react';
import { studentsAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',
  success: '#10B981',
  danger: '#EF4444',
  warning: '#F59E0B',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
  surface: '#FFFFFF'
};

const Enrollment = ({ onSuccess }) => {
  // ============ STATE ============
  const [formData, setFormData] = useState({
    name: '',
    email: ''
  });
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState(null);
  const [messageType, setMessageType] = useState('info');

  // ============ FILE HANDLING ============

  const handleFileSelect = (e) => {
    const selectedFile = e.target.files[0];

    if (!selectedFile) return;

    // ✅ ACCEPTE TOUS LES FORMATS (pas de limite!)
    console.log('📸 File selected:', selectedFile.name, selectedFile.type, selectedFile.size);

    setFile(selectedFile);

    // ✅ Créer preview
    const reader = new FileReader();
    reader.onload = (event) => {
      setPreview(event.target.result);
      showMessage(`✅ Image sélectionnée (${(selectedFile.size / 1024 / 1024).toFixed(2)} MB)`, 'success');
    };
    reader.readAsDataURL(selectedFile);
  };

  // ============ FORM HANDLING ============

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage(null);

    try {
      // ✅ Validation
      if (!formData.name.trim()) {
        showMessage('❌ Le nom est requis', 'error');
        setLoading(false);
        return;
      }

      if (!file) {
        showMessage('❌ Sélectionne une image', 'error');
        setLoading(false);
        return;
      }

      console.log('📸 [ENROLLMENT] Starting enrollment...');
      console.log('📸 [ENROLLMENT] Name:', formData.name);
      console.log('📸 [ENROLLMENT] Email:', formData.email);
      console.log('📸 [ENROLLMENT] File:', file.name, file.size, file.type);

      // ✅ Lire le fichier en base64
      const fileContent = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });

      console.log('✅ [ENROLLMENT] File encoded to base64');

      // ✅ APPEL API avec base64 image
      showMessage('⏳ Enrôlement en cours...', 'info');

      const response = await studentsAPI.enrollFromImage(
        formData.name,
        formData.email || null,
        fileContent  // ✅ Envoyer base64
      );

      console.log('✅ [ENROLLMENT] API Response:', response.data);

      // ✅ SUCCESS
      showMessage(`✅ ${response.data.message} (ID: ${response.data.student_id})`, 'success');

      // Reset form
      setFormData({ name: '', email: '' });
      setFile(null);
      setPreview(null);

      // Callback
      if (onSuccess) {
        onSuccess();
      }
    } catch (error) {
      console.error('❌ [ENROLLMENT] Error:', error.response?.data || error.message);

      const errorMsg = error.response?.data?.error || error.message || 'Enrollment failed';
      showMessage(`❌ ${errorMsg}`, 'error');
    } finally {
      setLoading(false);
    }
  };

  const showMessage = (msg, type) => {
    setMessage(msg);
    setMessageType(type);
    if (type === 'success' || type === 'error') {
      setTimeout(() => setMessage(null), 5000);
    }
  };

  // ============ RENDER ============

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.title}>➕ Enrôler un Nouvel Étudiant</h2>
        <p style={styles.subtitle}>
          Ajoute une photo claire du visage pour l'enrôlement biométrique
        </p>

        {/* MESSAGE */}
        {message && (
          <div
            style={{
              ...styles.message,
              backgroundColor: {
                success: '#DCFCE7',
                error: '#FEE2E2',
                info: '#DBEAFE',
                warning: '#FEF3C7'
              }[messageType],
              color: {
                success: '#166534',
                error: '#991B1B',
                info: '#0C4A6E',
                warning: '#92400E'
              }[messageType]
            }}
          >
            {message}
          </div>
        )}

        <form onSubmit={handleSubmit} style={styles.form}>
          {/* NOM */}
          <div style={styles.formGroup}>
            <label style={styles.label}>👤 Nom complet *</label>
            <input
              type="text"
              name="name"
              value={formData.name}
              onChange={handleInputChange}
              placeholder="Ahmed Hassan"
              style={styles.input}
              disabled={loading}
              required
            />
          </div>

          {/* EMAIL */}
          <div style={styles.formGroup}>
            <label style={styles.label}>📧 Email (optionnel)</label>
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleInputChange}
              placeholder="ahmed@example.com"
              style={styles.input}
              disabled={loading}
            />
          </div>

          {/* IMAGE UPLOAD */}
          <div style={styles.formGroup}>
            <label style={styles.label}>📸 Photo du visage *</label>

            {/* Upload Area */}
            <div style={styles.uploadArea}>
              <input
                type="file"
                accept="image/*"
                onChange={handleFileSelect}
                style={styles.fileInput}
                disabled={loading}
                id="imageInput"
              />
              <label htmlFor="imageInput" style={styles.uploadLabel}>
                <div style={styles.uploadContent}>
                  <div style={styles.uploadIcon}>📸</div>
                  <div style={styles.uploadText}>
                    {file ? (
                      <>
                        <strong>✅ {file.name}</strong>
                        <p style={styles.uploadSubtext}>
                          {(file.size / 1024).toFixed(2)} KB
                        </p>
                      </>
                    ) : (
                      <>
                        <strong>Clique pour uploader</strong>
                        <p style={styles.uploadSubtext}>
                          ou glisse un fichier (tous formats)
                        </p>
                      </>
                    )}
                  </div>
                </div>
              </label>
            </div>
          </div>

          {/* PREVIEW */}
          {preview && (
            <div style={styles.previewContainer}>
              <p style={{ margin: '0 0 10px 0', fontWeight: 600 }}>Aperçu:</p>
              <img
                src={preview}
                alt="Preview"
                style={styles.previewImage}
              />
              <button
                type="button"
                onClick={() => {
                  setFile(null);
                  setPreview(null);
                  setMessage(null);
                }}
                style={styles.removeBtn}
              >
                ✖️ Retirer
              </button>
            </div>
          )}

          {/* TIPS */}
          <div style={styles.tipsBox}>
            <p style={styles.tipsTitle}>💡 Conseils pour une bonne qualité:</p>
            <ul style={styles.tipsList}>
              <li>Visage bien visible et centré</li>
              <li>Bonne luminosité (pas de contre-jour)</li>
              <li>Photo nette (pas floue)</li>
              <li>Tous les formats image sont acceptés</li>
            </ul>
          </div>

          {/* SUBMIT BUTTON */}
          <button
            type="submit"
            style={{
              ...styles.submitBtn,
              opacity: loading || !file ? 0.6 : 1,
              cursor: loading || !file ? 'not-allowed' : 'pointer'
            }}
            disabled={loading || !file}
          >
            {loading ? '⏳ Enrôlement en cours...' : '✅ Enrôler l\'étudiant'}
          </button>
        </form>
      </div>
    </div>
  );
};

